import java.util.List;

public class PecsDemo {

    // Producer Extends: We only READ from the list 'source'
    public static double sumOfList(List<? extends Number> source) {
        double sum = 0.0;
        for (Number n : source) {
            sum += n.doubleValue();
        }
        return sum;
    }

    // Consumer Super: We only WRITE into the list 'destination'
    public static void addIntegers(List<? super Integer> destination) {
        for (int i = 1; i <= 3; i++) {
            destination.add(i); // Safe to write Integer and its subtypes
        }
    }

    // Combined PECS signature: copying from producer to consumer
    public static <T> void copy(List<? extends T> source, List<? super T> destination) {
        for (T item : source) {
            destination.add(item);
        }
    }
}
